/* ============================================
   TOGGLE SWITCH COMPONENT
   Binary on/off switch with a check in the thumb.
   The track is SwitchIndicator, a presentational
   piece every host that offers a switch draws
   (ToggleSwitch itself, InspectorToggleSwitch,
   SelectionCard's toggle mode): its state is
   keyed on the track's own modifiers.
   ============================================ */

.ds-toggle-switch {
  /* Layout */
  display: inline-flex;
  align-items: center;
  gap: var(--gap-200); /* 8px */

  /* Reset */
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  color: var(--color-text-primary);
  font-family: var(--font-paragraph-family);
}

/* ============================================
   TRACK — SwitchIndicator
   ============================================ */

.ds-toggle-switch__track {
  position: relative;
  display: inline-block;
  width: 42px;
  height: 24px;
  border-radius: var(--radius-pill);
  background: var(--color-action-primary-bg);
  transition: background-color var(--motion-duration-slow) var(--motion-ease-standard);
  flex-shrink: 0;
}

/* ============================================
   THUMB
   ============================================ */

.ds-toggle-switch__thumb {
  position: absolute;
  top: 2px;
  right: 2px;
  width: 20px;
  height: 20px;
  background: var(--color-control-thumb);
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  transition: transform var(--motion-duration-slow) var(--motion-ease-spring);
}

/* The same SVG check Checkbox draws, so the two controls show one tick.
   14px inside the 20px thumb: the smallest icon step is also 20px, which
   would fill the thumb edge to edge. */
.ds-toggle-switch__thumb-icon {
  display: block;
  width: 14px;
  height: 14px;
  color: var(--color-action-primary-bg);
}

/* ============================================
   LABEL
   ============================================ */

.ds-toggle-switch__label {
  font-family: var(--font-paragraph-family);
  font-size: var(--font-paragraph-size);
  font-weight: var(--font-paragraph-weight);
  line-height: var(--font-paragraph-line-height);
  /* The root is a <button>, whose UA style centres text — without this,
     a label short enough to undershoot any width the layout gives it
     floats away from the track instead of hugging the gap. */
  text-align: left;
}

/* ============================================
   STATES
   Keyed on the track, so an indicator drawn by
   another host shows the same states.
   ============================================ */

/* Off / Unchecked state — thumb moves to the left */
.ds-toggle-switch__track--off {
  background: var(--color-text-secondary);
}

.ds-toggle-switch__track--off .ds-toggle-switch__thumb {
  transform: translateX(-18px);
}

/* ============================================
   FOCUS
   The same ring as Checkbox and RadioButton, on
   the track rather than around the label.
   ============================================ */

.ds-toggle-switch:focus-visible {
  outline: none;
}

.ds-toggle-switch:focus-visible .ds-toggle-switch__track {
  outline: 2px solid var(--color-action-primary-bg);
  outline-offset: 2px;
}

/* ============================================
   DISABLED STATE
   ============================================ */

.ds-toggle-switch--disabled {
  opacity: 0.4;
  cursor: not-allowed;
}

/* ============================================
   SIZE — COMPACT
   ============================================ */

.ds-toggle-switch__track--compact {
  width: 34px;
  height: 20px;
}

.ds-toggle-switch__track--compact .ds-toggle-switch__thumb {
  width: 16px;
  height: 16px;
}

/* 12px inside the 16px compact thumb, for the same reason as the default. */
.ds-toggle-switch__track--compact .ds-toggle-switch__thumb-icon {
  width: 12px;
  height: 12px;
}

.ds-toggle-switch__track--compact.ds-toggle-switch__track--off .ds-toggle-switch__thumb {
  transform: translateX(-14px);
}

.ds-toggle-switch--compact .ds-toggle-switch__label {
  font-size: var(--font-paragraph-sm-size);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
}

/* Helper line: label and helper stack in a text column beside the track;
   the track aligns to the first text line rather than the column's centre. */
.ds-toggle-switch--has-helper {
  align-items: flex-start;
}

.ds-toggle-switch__text {
  display: flex;
  flex-direction: column;
  gap: var(--gap-050); /* 2px */
}

.ds-toggle-switch__helper {
  font-family: var(--font-paragraph-sm-family);
  font-size: var(--font-paragraph-sm-size);
  font-weight: var(--font-paragraph-sm-weight);
  line-height: var(--font-paragraph-sm-line-height);
  letter-spacing: var(--font-paragraph-sm-letter-spacing);
  color: var(--color-text-tertiary);
  text-align: left;
}

.ds-toggle-switch--error .ds-toggle-switch__helper {
  color: var(--color-status-error-border);
}

'use client';

import React, { useId, useState } from 'react';
import { CheckIcon } from '../Checkbox/Checkbox';
import './ToggleSwitch.css';

/** Props owned by ToggleSwitch itself — everything else falls through to the <button>. */
type ToggleSwitchOwnProps = {
  /**
   * Whether the toggle is on, controlled. Leave undefined to let the switch
   * keep its own state, seeded from `defaultChecked`.
   */
  checked?: boolean;
  /** Whether the toggle starts on when uncontrolled (`checked` undefined). Defaults to true, so an uncontrolled switch starts on unless this is false. */
  defaultChecked?: boolean;
  /** Label text displayed next to the toggle */
  label?: string;
  /** Whether to show the label */
  showLabel?: boolean;
  /** Helper or error message rendered under the label text */
  helperText?: string;
  /** Error state — recolours the helper text and marks the switch invalid */
  error?: boolean;
  /** Component size */
  size?: 'default' | 'compact';
  /** Called with the next checked state when toggled */
  onCheckedChange?: (checked: boolean) => void;
  /** Additional CSS classes */
  className?: string;
  /**
   * Legacy change handler, kept for backwards compatibility.
   *
   * @deprecated Use `onCheckedChange` instead.
   */
  onChange?: (checked: boolean) => void;
  /**
   * Legacy accessible-name prop.
   *
   * @deprecated Pass the native `aria-label` attribute instead.
   */
  ariaLabel?: string;
};

export interface ToggleSwitchProps
  extends ToggleSwitchOwnProps,
    Omit<React.ComponentPropsWithoutRef<'button'>, keyof ToggleSwitchOwnProps | 'type'> {}

/**
 * ToggleSwitch component from Figma design system.
 * Used for binary on/off settings like theme switching.
 *
 * Renders a `<button role="switch">`, forwards a ref to it, and spreads
 * unrecognised props onto it.
 */
export const ToggleSwitch = React.forwardRef<HTMLButtonElement, ToggleSwitchProps>(
  (
    {
      checked: checkedProp,
      defaultChecked = true,
      label = 'Toggle',
      showLabel = true,
      helperText,
      error = false,
      disabled = false,
      size = 'default',
      onCheckedChange,
      onChange,
      onClick,
      className = '',
      ariaLabel,
      ...rest
    },
    ref,
  ) => {
    const baseClass = 'ds-toggle-switch';
    const [internalChecked, setInternalChecked] = useState(defaultChecked);
    const isControlled = checkedProp !== undefined;
    const checked = isControlled ? checkedProp : internalChecked;
    const generatedId = useId();
    const helperId = helperText ? `${generatedId}-helper` : undefined;
    const describedBy = helperId ?? rest['aria-describedby'];
    const classes = [
      baseClass,
      size === 'compact' ? `${baseClass}--compact` : '',
      checked ? '' : `${baseClass}--off`,
      disabled ? `${baseClass}--disabled` : '',
      helperText ? `${baseClass}--has-helper` : '',
      error ? `${baseClass}--error` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');

    const handleClick = (e: React.MouseEvent<HTMLButtonElement>) => {
      onClick?.(e);
      if (disabled) return;
      if (!isControlled) setInternalChecked(!checked);
      onCheckedChange?.(!checked);
      onChange?.(!checked);
    };

    return (
      <button
        {...rest}
        ref={ref}
        type="button"
        className={classes}
        onClick={handleClick}
        disabled={disabled}
        role="switch"
        aria-checked={checked}
        aria-label={rest['aria-label'] || ariaLabel || label}
        aria-describedby={describedBy}
        aria-invalid={error || undefined}
      >
        <SwitchIndicator checked={checked} size={size} />
        {/* Without a helper the label stays a bare span, so existing markup
            (and layout) is untouched; with one, label and helper stack in a
            text column beside the track. */}
        {helperText ? (
          <span className={`${baseClass}__text`}>
            {showLabel && <span className={`${baseClass}__label`}>{label}</span>}
            <span className={`${baseClass}__helper`} id={helperId}>
              {helperText}
            </span>
          </span>
        ) : (
          showLabel && <span className={`${baseClass}__label`}>{label}</span>
        )}
      </button>
    );
  },
);

ToggleSwitch.displayName = 'ToggleSwitch';

/* ============================================
   SWITCH INDICATOR — the track on its own
   ============================================ */

/** Props owned by SwitchIndicator itself — everything else falls through to the <span>. */
type SwitchIndicatorOwnProps = {
  /** Whether the switch is on. */
  checked?: boolean;
  /** Track size: `default` is 42×24px, `compact` 34×20px. */
  size?: 'default' | 'compact';
  /** Additional CSS classes */
  className?: string;
};

export interface SwitchIndicatorProps
  extends SwitchIndicatorOwnProps,
    Omit<React.ComponentPropsWithoutRef<'span'>, keyof SwitchIndicatorOwnProps | 'children'> {}

/**
 * The switch's track and thumb, as a presentational piece for a host that
 * is itself the control: InspectorToggleSwitch's bar and SelectionCard's
 * toggle mode draw it, so a switch looks and moves the same wherever it
 * appears. Hidden from assistive technology; the host carries
 * `role="switch"` and the state.
 */
export const SwitchIndicator = React.forwardRef<HTMLSpanElement, SwitchIndicatorProps>(
  ({ checked = false, size = 'default', className = '', ...rest }, ref) => {
    const base = 'ds-toggle-switch__track';
    const classes = [
      base,
      checked ? '' : `${base}--off`,
      size === 'compact' ? `${base}--compact` : '',
      className,
    ]
      .filter(Boolean)
      .join(' ');
    return (
      <span aria-hidden="true" {...rest} ref={ref} className={classes}>
        <span className="ds-toggle-switch__thumb">
          <CheckIcon className="ds-toggle-switch__thumb-icon" />
        </span>
      </span>
    );
  },
);

SwitchIndicator.displayName = 'SwitchIndicator';
